import {createQuizInsets} from './quiz-insets.mjs';
import {getMapScene} from './map-scene.mjs';
import {createRound,answer,advance,score} from './quiz-engine.mjs';
import {createNameRound,submitName,nameHint,nameScore,serializeNameRound} from './name-quiz-engine.mjs';
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;};
export const firstLevelPool=(records,overseas=false,exclude=[])=>records.filter(r=>!exclude.includes(r.id)&&r.level===1&&r.bounds&&r.center&&!r.nonGeographic&&r.quizEligible!==false&&(overseas||!r.overseas));
const storageKey=country=>'boundary-atlas-first-quiz-v1:'+country;
const read=country=>{try{const data=JSON.parse(localStorage.getItem(storageKey(country)));return data&&typeof data==='object'&&!Array.isArray(data)?data:{};}catch{return{};}};
const write=(country,value)=>{try{localStorage.setItem(storageKey(country),JSON.stringify(value));return true;}catch{return false;}};
// Both map adapters expose the same small quiz interface. No deeper geometry is requested.
export function createFirstLevelQuiz(map,host,adapter){
 const {country,sidebar,prefix}=adapter,definition=globalThis.AtlasCountries.countries[country];if(!definition.quiz)return;
 const tabs=sidebar.querySelector('.panel-tabs'),scroll=sidebar.querySelector('.sidebar-scroll'),tab=node('button','Quiz'),panel=node('section');tab.id=prefix+'-tab-quiz';tab.type='button';tab.setAttribute('aria-controls',prefix+'-quiz-panel');tab.setAttribute('aria-pressed','false');panel.id=prefix+'-quiz-panel';panel.hidden=true;tabs.append(tab);scroll.append(panel);
 panel.innerHTML=`<div data-q="setup"><h2>First-level quiz</h2><p class="quiz-instruction">${definition.levelNames[0]} · ${definition.en}</p><label class="field-label" for="${prefix}-quiz-type">Quiz type</label><select id="${prefix}-quiz-type"><option value="find">Find the place</option><option value="name">Name every place</option></select><label class="field-label" data-q="length-label" for="${prefix}-quiz-length">Questions</label><select id="${prefix}-quiz-length"><option value="10">10</option><option value="20">20</option><option value="all">All</option></select><label data-q="overseas-option" class="quiz-toggle"><span>Include overseas territories</span><input data-q="overseas" type="checkbox"></label><p data-q="count" class="quiz-note"></p><button data-q="start" class="quiz-primary">Start quiz</button><button data-q="resume" class="quiz-text-button" hidden>Resume saved round</button><p data-q="best" class="quiz-note" hidden></p></div><div data-q="round" hidden><div class="quiz-progress"><span data-q="progress"></span><span data-q="score"></span></div><div class="quiz-progress-track"><div data-q="bar"></div></div><h2 data-q="question" class="first-quiz-question" tabindex="-1"></h2><p data-q="local" class="country-local"></p><p data-q="instruction" class="quiz-instruction"></p><form data-q="form" class="name-entry" hidden><label class="sr-only" for="${prefix}-quiz-answer">Place name</label><input id="${prefix}-quiz-answer" autocomplete="off" placeholder="Enter a place name"><button class="quiz-primary" type="submit">Add</button></form><div data-q="feedback" class="quiz-feedback" role="status" hidden></div><div class="quiz-round-actions"><button data-q="reveal" class="quiet-button">Show answer</button><button data-q="hint" class="quiet-button" hidden>Hint</button><button data-q="view" class="quiet-button" hidden>View answer</button><button data-q="next" class="quiz-primary" hidden>Next question</button></div><div data-q="review" class="quiz-review"></div><button data-q="end" class="quiz-text-button">End quiz</button></div>`;
 const $=name=>panel.querySelector('[data-q="'+name+'"]'),type=panel.querySelector('#'+prefix+'-quiz-type'),length=panel.querySelector('#'+prefix+'-quiz-length'),input=panel.querySelector('#'+prefix+'-quiz-answer');
 const prompt=node('div',null,'quiz-map-prompt first-quiz-map');prompt.hidden=true;prompt.innerHTML='<span data-progress></span><strong data-name></strong><span data-local></span><button type="button">Show answer</button>';document.getElementById('map-shell').append(prompt);
 for(const b of [...panel.querySelectorAll('button'),prompt.querySelector('button')])b.dataset.quizNav='';
 let active=false,starting=false,round,naming=false,pool=[],saved,review=null,labels=[],paints,solved=new Set(),wrong=null,revealed=false,overseas=false,returnPanel=null,insets;
 const clearLabels=()=>{for(const l of labels)l.remove();labels=[];};
 const name=r=>[r.en,r.local&&r.local!==r.en?r.local:''].filter(Boolean).join(' · ');
 const entry=r=>({feature:{properties:{adcode:r.id}},record:r});
 const find=id=>pool.find(r=>r.id===id);
 const open=()=>{if(active)return;returnPanel=[...sidebar.querySelectorAll('.sidebar-scroll > section')].find(s=>s!==panel&&!s.hidden)?.id||returnPanel;for(const section of sidebar.querySelectorAll('.sidebar-scroll > section'))section.hidden=section!==panel;for(const b of tabs.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b===tab));panel.hidden=false;setup();};
 function setup(){const records=adapter.records();$('overseas-option').hidden=!records.some(r=>r.level===1&&r.overseas);const available=firstLevelPool(records,$('overseas').checked,definition.quiz.exclude||[]);const isName=type.value==='name';length.hidden=$('length-label').hidden=isName;$('count').textContent=available.length+' places available · first level only';const data=read(country),scope=$('overseas').checked?'all':'core',draft=data.draft;$('resume').hidden=!isName||!draft||draft.overseas!==$('overseas').checked;$('best').textContent=data.best?.[scope]?.label||'';$('best').hidden=!isName||!$('best').textContent;$('start').disabled=starting||!adapter.ready()||!available.length;}
 function updateInsets(){insets?.update({records:pool,solved,review,wrong,missed:naming&&revealed?new Set(pool.filter(r=>!round.found.has(r.id)).map(r=>r.id)):null,canAnswer:active&&!naming&&!round.complete&&!round.results[round.index]&&!host.isMoving()});}
 function labelsUpdate(){updateInsets();clearLabels();if(!active||host.isMoving()||map.isMoving())return;const shown=pool.filter(r=>solved.has(r.id)||r.id===review?.id);labels=window.AtlasLabels.render(map,shown.map(r=>({...r,selected:r===review})),'korea-marker');}
 function paint(){if(!active)return;const fill=country+'-first-fill';for(const r of pool)map.setFeatureState({source:country+'-first',id:r.id},{quizCorrect:solved.has(r.id)||review?.id===r.id,quizWrong:wrong===r.id||naming&&revealed&&!round.found.has(r.id)});map.setPaintProperty(fill,'fill-color',['case',['boolean',['feature-state','quizCorrect'],false],'#548165',['boolean',['feature-state','quizWrong'],false],'#b44737','#e9e5dc']);map.setPaintProperty(fill,'fill-opacity',1);if(map.getLayer(country+'-first-lines'))map.setLayoutProperty(country+'-first-lines','visibility','visible');adapter.review(review);labelsUpdate();}
 function store(){if(!naming||!round)return;const data=read(country);if(round.complete||revealed)delete data.draft;else data.draft={...serializeNameRound(round),overseas};if(round.complete){const s=nameScore(round);const key=overseas?'all':'core';if(!data.best||typeof data.best!=='object')data.best={};const best=Math.max(s.unassisted,Number(data.best[key]?.score)||0);data.best[key]={score:best,label:'Personal best · '+best+' / '+s.total+' without hints'};}if(!write(country,data)){$('feedback').hidden=false;$('feedback').textContent='Browser storage is unavailable. Keep this tab open to retain progress.';}}
 async function start(resume=false){if(active||starting||host.isBusy()||host.isMoving()||!adapter.ready())return;starting=true;setup();saved={adapter:adapter.capture(),home:document.getElementById('home').textContent,hint:document.getElementById('map-hint').textContent};try{await adapter.begin();overseas=$('overseas').checked;pool=firstLevelPool(adapter.records(),overseas,definition.quiz.exclude||[]);naming=type.value==='name';round=naming?createNameRound(pool.map(r=>({code:r.id,en:r.en,zh:r.local||'',aliases:[...(r.aliases||[]),r.en.replace(/\s+(?:State|Province|Region)$/i,'')]})),resume?read(country).draft:undefined):createRound(pool.map(entry),length.value);solved=new Set(naming?round.found:[]);wrong=null;review=null;revealed=false;const fill=country+'-first-fill';insets=createQuizInsets(definition.quiz.insets?.filter(id=>pool.some(r=>r.id===id)),prompt,choose);active=true;adapter.onActiveChange?.();adapter.hideLabels();host.setQuizActive(true);paints={color:getMapScene(map)?.basePaint(fill,'fill-color')??map.getPaintProperty(fill,'fill-color'),opacity:getMapScene(map)?.basePaint(fill,'fill-opacity')??map.getPaintProperty(fill,'fill-opacity')??1};sidebar.dataset.quiz='true';for(const b of tabs.querySelectorAll('button'))b.disabled=b!==tab;for(const s of sidebar.querySelectorAll('.sidebar-scroll > section'))s.hidden=s!==panel;panel.hidden=false;tab.setAttribute('aria-pressed','true');$('setup').hidden=true;$('round').hidden=false;$('feedback').hidden=true;$('review').replaceChildren();input.value='';document.getElementById('home').textContent='End quiz';document.getElementById('map-hint').textContent=naming?'Type place names':'Click the named place';paint();render();store();await fit();if(naming)input.focus({preventScroll:true});else $('question').focus({preventScroll:true});}finally{starting=false;}}
 function allBounds(){const bs=pool.map(r=>r.bounds);return[[Math.min(...bs.map(b=>b[0][0])),Math.min(...bs.map(b=>b[0][1]))],[Math.max(...bs.map(b=>b[1][0])),Math.max(...bs.map(b=>b[1][1]))]];}
 async function fit(){if(insets&&!naming){await Promise.resolve();await window.AtlasSheet?.collapse();}return host.fit(definition.quiz.bounds||allBounds(),definition.quiz.bounds?(definition.home.maxZoom||8)-1:8,{manual:true});}
 function render(){const done=naming?round.complete||revealed:round.complete;const s=naming?nameScore(round):score(round),result=!naming&&round.results[round.index],r=!naming&&round.questions[round.index].record;$('progress').textContent=naming?s.found+' / '+s.total+' named':done?'Round complete':'Question '+(round.index+1)+' / '+s.total;$('score').textContent=naming?s.unassisted+' without hints':s.correct+' correct';$('bar').style.width=(naming?s.found:s.answered)/s.total*100+'%';$('question').textContent=done?'Round complete':naming?'Name every place':r.en;$('local').textContent=!done&&!naming&&r.local!==r.en?r.local||'':'';$('local').lang=r?.localLang||definition.lang;$('instruction').textContent=done?(naming?s.found+' of '+s.total+' named · '+s.unassisted+' without hints':s.correct+' correct · '+s.incorrect+' incorrect · '+s.skipped+' answers shown'):naming?'English and local names are accepted.':'Click the named place on the map.';$('form').hidden=!naming||done;$('hint').hidden=!naming||done;$('reveal').hidden=done||(!naming&&!!result);$('reveal').textContent=naming?'Finish & show remaining':'Show answer';$('next').hidden=naming||done||!result;$('next').textContent=!naming&&round.index+1===round.questions.length?'See results':'Next question';$('view').hidden=naming||done||!result;$('end').textContent=naming&&!done?'Save & exit':'End quiz';prompt.hidden=done;prompt.querySelector('[data-progress]').textContent=$('progress').textContent;prompt.querySelector('[data-name]').textContent=$('question').textContent;prompt.querySelector('[data-local]').lang=r?.localLang||definition.lang;prompt.querySelector('[data-local]').textContent=naming?'':result?{correct:'Correct',incorrect:'Incorrect',skipped:'Answer shown'}[result.status]:$('local').textContent;prompt.querySelector('button').textContent=naming?'Enter names':result?'Next':'Show answer';if(done)renderReview();if(naming)renderNamed(done);updateInsets();host.controls();}
 function renderReview(){const box=$('review');box.replaceChildren();if(naming)return;for(const r of round.results.filter(r=>r.status!=='correct')){const b=node('button',name(find(r.expected)));b.type='button';b.onclick=()=>view(find(r.expected));box.append(b);}}
 function renderNamed(done){const box=$('review');box.replaceChildren();for(const r of pool.filter(r=>done||round.found.has(r.id))){const b=node('button',name(r)+(round.found.has(r.id)?' ✓':''));b.type='button';b.onclick=()=>view(r);box.append(b);}}
 function feedback(text,status){$('feedback').hidden=false;$('feedback').textContent=text;$('feedback').dataset.status=status;}
 function choose(id=null){if(!active||naming||host.isMoving())return;const result=answer(round,id);if(!result)return;review=find(result.expected);wrong=result.status==='incorrect'?id:null;if(result.status==='correct')solved.add(review.id);feedback(result.status==='correct'?'Correct':result.status==='skipped'?'Answer shown · '+name(review):'Incorrect · you selected '+name(find(id))+'. Correct: '+name(review),result.status);paint();render();$('next').focus({preventScroll:true});}
 async function next(){if(!active||naming||host.isMoving()||!advance(round))return;wrong=null;review=null;$('feedback').hidden=true;paint();render();if(!round.complete){await fit();$('question').focus({preventScroll:true});}}
 async function view(r){if(!active||host.isMoving())return;review=r;paint();if(insets?.has(r.id)){await fit();insets?.focus(r.id);}else await host.fit(r.bounds,11);}
 async function end(){if(!active)return;if(host.isMoving()){if(!host.stopCamera)return;await host.stopCamera();if(!active)return;}store();active=false;adapter.onActiveChange?.();insets?.remove();insets=undefined;clearLabels();document.getElementById('quiz-crosshair').hidden=true;prompt.hidden=true;for(const r of pool)map.removeFeatureState({source:country+'-first',id:r.id});map.setPaintProperty(country+'-first-fill','fill-color',paints.color);map.setPaintProperty(country+'-first-fill','fill-opacity',paints.opacity);adapter.review(null);host.setQuizActive(false);delete sidebar.dataset.quiz;for(const b of tabs.querySelectorAll('button'))b.disabled=false;document.getElementById('home').textContent=saved.home;document.getElementById('map-hint').textContent=saved.hint;await adapter.restore(saved.adapter);panel.hidden=true;tab.setAttribute('aria-pressed','false');if(returnPanel){for(const section of sidebar.querySelectorAll('.sidebar-scroll > section'))section.hidden=section.id!==returnPanel;for(const b of tabs.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.getAttribute('aria-controls')===returnPanel));}$('setup').hidden=false;$('round').hidden=true;setup();}
 function picked(point){const id=country+'-first-fill';if(!map.getLayer(id))return;const f=map.queryRenderedFeatures(point,{layers:[id]})[0];return f&&pool.find(r=>r.id===String(f.properties.id));}
 map.on('click',e=>{if(active&&!naming&&!host.isMoving()){const r=picked(e.point);if(r)choose(r.id);}});map.on('moveend',labelsUpdate);map.on('movestart',()=>{clearLabels();updateInsets();});
 map.getCanvas().addEventListener('keydown',e=>{if(active&&!naming&&e.key==='Enter'){e.preventDefault();const r=picked([map.getContainer().clientWidth/2,map.getContainer().clientHeight/2]);if(r)choose(r.id);}});
 tabs.addEventListener('click',event=>{if(!active&&event.target.closest('button')!==tab)panel.hidden=true;},true);
 map.getCanvas().addEventListener('focus',()=>{if(active)document.getElementById('quiz-crosshair').hidden=naming;});map.getCanvas().addEventListener('blur',()=>{if(active)document.getElementById('quiz-crosshair').hidden=true;});
 tab.onclick=open;type.onchange=length.onchange=$('overseas').onchange=setup;$('start').onclick=()=>start();$('resume').onclick=()=>start(true);$('end').onclick=end;$('next').onclick=next;$('view').onclick=()=>view(review);$('reveal').onclick=()=>{if(!active||host.isMoving())return;if(naming){revealed=true;store();paint();render();}else choose();};$('hint').onclick=()=>{if(!active||host.isMoving())return;const h=nameHint(round);if(h){feedback('Starts with '+h.en,'hint');store();render();}};
 $('form').onsubmit=e=>{e.preventDefault();if(!active||!naming||round.complete||revealed||e.isComposing)return;const r=submitName(round,input.value);if(r.status==='correct'){solved.add(r.place.code);input.value='';feedback(name(find(r.place.code))+' · correct','correct');paint();store();render();}else feedback(r.status==='duplicate'?'Already named.':r.status==='ambiguous'?'Use the full place name.':'No match. Try its English or local name.',r.status);input.focus({preventScroll:true});};
 prompt.querySelector('button').onclick=()=>{if(naming){sidebar.scrollIntoView({block:'start'});input.focus();}else if(round.results[round.index])next();else choose();};
 return{get active(){return active;},open,end,fit,paint,labels:labelsUpdate,setup};
}
